<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?= csrfTokenMeta() ?><title>Restore Preview - <?= htmlspecialchars(APP_SHORT_NAME) ?></title><?= google_fonts_tag('Inter:wght@400;500;600;700;800') ?><script src="<?= asset_url('lucide') ?>"></script><link rel="stylesheet" href="../assets/css/sidebar.css?v=20260929-groups"><style>
:root{--ink:#172033;--muted:#64748b;--line:#e2e8f0;--bg:#f6f8fb;--primary:#6750a4;--good:#15803d;--warn:#a16207;--bad:#b91c1c}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"Segoe UI",sans-serif}.content{padding:30px 36px;max-width:1700px}.hero{background:linear-gradient(135deg,#334155,#0f172a);color:#fff;border-radius:16px;padding:28px 32px;margin-bottom:20px}.hero h1{margin:0 0 7px;font-size:27px;display:flex;align-items:center;gap:10px}.hero p{margin:0;opacity:.9;font-size:14px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:18px;box-shadow:0 1px 3px #0000000d}.notice{padding:12px 14px;border-radius:9px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-size:13px;margin-bottom:16px}.form-grid{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:end}.field label{display:block;font-size:12px;font-weight:800;color:#475569;margin-bottom:5px}.field select{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;background:#fff;font:inherit;font-size:13px}.btn,td button{border:1px solid #cbd5e1;background:#fff;border-radius:8px;padding:9px 12px;font:inherit;font-size:12px;font-weight:700;cursor:pointer}.btn-primary{border:0;background:var(--primary);color:#fff}.btn-danger{color:var(--bad)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:1200px}th,td{padding:10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:12px}th{background:#f8fafc;color:#475569;font-size:11px;text-transform:uppercase}.status{display:inline-flex;padding:4px 8px;border-radius:999px;background:#eef2f7;font-weight:800}.status.completed{background:#ecfdf3;color:var(--good)}.status.running,.status.queued{background:#eff6ff;color:#1d4ed8}.status.completed_with_errors{background:#fffbeb;color:var(--warn)}.status.failed{background:#fef2f2;color:var(--bad)}.status.cleaned{background:#f1f5f9;color:#475569}.small{font-size:11px;color:var(--muted)}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.logs,.report{max-height:320px;overflow:auto;background:#0f172a;color:#dbeafe;border-radius:9px;padding:12px;font:12px Consolas,monospace;white-space:pre-wrap}.empty{padding:28px;text-align:center;color:var(--muted)}@media(max-width:900px){.content{padding:20px}.form-grid{grid-template-columns:1fr}}
</style></head><body><?php require_once '../includes/sidebar_nav.php'; ?><main class="content"><section class="hero"><h1><i data-lucide="database-zap"></i> Restore Preview &amp; Validation</h1><p>Import a verified database backup into an isolated staging database and validate PDF references before any production recovery decision.</p></section><section class="card"><div class="notice"><strong>Safety boundary:</strong> this phase never overwrites the live database. The SQL dump is normalized into a system-created staging database, then table counts, hashes, and active PDF references are checked.</div><form id="form"><div class="form-grid"><div class="field"><label for="backup">Completed database backup</label><select id="backup" required><option value="">Loading verified backups...</option></select></div><button class="btn btn-primary" id="start" type="submit">Start restore preview</button></div></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Status</th><th>Backup</th><th>Staging database</th><th>Tables</th><th>PDF references</th><th>Created</th><th>Actions</th></tr></thead><tbody id="jobs"><tr><td colspan="8" class="empty">Loading...</td></tr></tbody></table></div><div class="pagination"><span class="small" id="summary">Loading...</span><span><button id="prev" disabled>Previous</button> <button id="next" disabled>Next</button></span></div></section><section class="card" id="detail" hidden><h2 style="margin-top:0" id="detail-title">Preview details</h2><p class="small" id="detail-summary"></p><div class="logs" id="logs"></div><h3>Report</h3><pre class="report" id="report">No report loaded.</pre></section></main>
<script>
const api='../api/database_restore_preview.php',backupApi='../api/database_backup.php',csrf=document.querySelector('meta[name="csrf-token"]')?.content||'',backup=document.getElementById('backup'),jobs=document.getElementById('jobs'),summary=document.getElementById('summary');let page=1;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));
async function request(url,options){const response=await fetch(url,{credentials:'same-origin',...(options||{})});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'Restore preview request failed.');return data;}
function pdfSummary(item){return`${Number(item.pdf_present_count||0)} present / ${Number(item.pdf_missing_count||0)} missing / ${Number(item.pdf_invalid_count||0)} invalid`}
async function loadBackups(){const data=await request(`${backupApi}?action=list&page=1&per_page=100`);const completed=(data.jobs||[]).filter(item=>item.status==='completed');backup.innerHTML=completed.map(item=>`<option value="${Number(item.id)}">Backup #${Number(item.id)} — ${esc(item.created_at)} — ${esc(item.backup_folder)}</option>`).join('')||'<option value="">No completed verified backups available</option>';}
async function loadJobs(){const data=await request(`${api}?action=list&page=${page}&per_page=25`),p=data.pagination;page=p.page;summary.textContent=p.total?`Showing ${p.from}-${p.to} of ${p.total} restore preview job(s)`:'No restore previews yet';document.getElementById('prev').disabled=!p.has_previous;document.getElementById('next').disabled=!p.has_next;if(!data.jobs.length){jobs.innerHTML='<tr><td colspan="8" class="empty">No restore preview jobs yet.</td></tr>';return;}jobs.innerHTML=data.jobs.map(item=>`<tr><td>#${Number(item.id)}</td><td><span class="status ${esc(item.status)}">${esc(item.status)}</span><div class="small">${esc(item.last_error||'')}</div></td><td>#${Number(item.backup_job_id)}<div class="small">${esc(item.backup_folder)}</div></td><td>${esc(item.staging_database_name||'-')}</td><td>${Number(item.staging_table_count||0)} / ${Number(item.table_statements||0)}<div class="small">${Number(item.insert_statements||0)} INSERT statements</div></td><td>${pdfSummary(item)}</td><td>${esc(item.created_at||'')}</td><td><button data-detail="${Number(item.id)}">Details</button> <button data-report="${Number(item.id)}">Report</button> ${(item.status==='completed'||item.status==='completed_with_errors'||item.status==='failed')?`<button class="btn-danger" data-cleanup="${Number(item.id)}">Remove staging</button>`:''}</td></tr>`).join('');jobs.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>showDetail(Number(button.dataset.detail)).catch(error=>alert(error.message))));jobs.querySelectorAll('[data-report]').forEach(button=>button.addEventListener('click',()=>showReport(Number(button.dataset.report)).catch(error=>alert(error.message))));jobs.querySelectorAll('[data-cleanup]').forEach(button=>button.addEventListener('click',()=>cleanup(Number(button.dataset.cleanup)).catch(error=>alert(error.message))));}
async function showDetail(id){const data=await request(`${api}?action=job&job_id=${id}`);document.getElementById('detail').hidden=false;document.getElementById('detail-title').textContent=`Restore preview #${id} — ${data.job.status}`;document.getElementById('detail-summary').textContent=`Backup #${data.job.backup_job_id} | staging DB: ${data.job.staging_database_name||'-'} | PDF references: ${pdfSummary(data.job)}`;document.getElementById('logs').textContent=(data.logs||[]).reverse().map(item=>`[${item.created_at}] ${String(item.level).toUpperCase()}: ${item.message}`).join('\n')||'No logs yet.';await showReport(id,true);}
async function showReport(id,silent=false){try{const data=await request(`${api}?action=report&job_id=${id}`);document.getElementById('detail').hidden=false;document.getElementById('report').textContent=JSON.stringify(data.report,null,2);}catch(error){if(!silent)throw error;document.getElementById('report').textContent=error.message;}}
async function cleanup(id){if(!confirm(`Remove the isolated staging database for preview #${id}? The original SQL backup will not be deleted.`))return;const form=new FormData();form.append('action','cleanup');form.append('job_id',id);form.append('csrf_token',csrf);await request(api,{method:'POST',body:form});await loadJobs();alert('The isolated staging database was removed.');}
document.getElementById('form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('start');button.disabled=true;const form=new FormData();form.append('action','create');form.append('backup_job_id',backup.value);form.append('csrf_token',csrf);try{const data=await request(api,{method:'POST',body:form});alert(`${data.message} Job ID: ${data.job_id}`);await loadJobs();}catch(error){alert(error.message);}finally{button.disabled=false;}});document.getElementById('prev').addEventListener('click',()=>{if(page>1){page--;loadJobs().catch(error=>alert(error.message));}});document.getElementById('next').addEventListener('click',()=>{page++;loadJobs().catch(error=>alert(error.message));});if(window.lucide)lucide.createIcons();Promise.all([loadBackups(),loadJobs()]).catch(error=>alert(error.message));setInterval(()=>loadJobs().catch(()=>{}),5000);
</script></body></html>
